import org.junit.Assert;
import org.junit.Test;
import org.jsoup.parser.*;
import org.jsoup.nodes.*;

public class XmlTreeBuilderTest {

    @Test
    public void parseInputBaseUriTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Document document = xmlTreeBuilder.parse("xml parsing test", "baseUri");
        Assert.assertNotNull(document);
    }

    @Test
    public void parseReaderBaseUriTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Document document = xmlTreeBuilder.parse(new StringReader("reading xml parsing test"), "baseUri");
        Assert.assertNotNull(document);
    }

    @Test
    public void parseFragmentInputBaseUriParserTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        List<Node> nodeList = xmlTreeBuilder.parseFragment("fragment parsing test", "baseUri", Parser.xmlParser());
        Assert.assertNotNull(nodeList);
    }

    @Test
    public void parseFragmentInputContextBaseUriParserTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Element context = new Element(Tag.valueOf("p"), "baseUri");
        List<Node> nodeList = xmlTreeBuilder.parseFragment("fragment parsing test", context, "baseUri", Parser.xmlParser());
        Assert.assertNotNull(nodeList);
    }

    @Test
    public void insertStartTagTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.StartTag startTag = new Token.StartTag();
        startTag.tagName = "p";
        xmlTreeBuilder.insert(startTag);
        Assert.assertEquals("p", xmlTreeBuilder.stack.getLast().nodeName());
    }

    @Test
    public void insertCharacterTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.Character character = new Token.Character().data("data");
        xmlTreeBuilder.insert(character);
        Assert.assertTrue(xmlTreeBuilder.stack.getLast() instanceof TextNode);
    }

    @Test
    public void insertDoctypeTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.Doctype doctype = new Token.Doctype();
        doctype.name("doctype");
        xmlTreeBuilder.insert(doctype);
        Assert.assertTrue(xmlTreeBuilder.stack.getLast() instanceof DocumentType);
    }

    @Test
    public void insertNodeTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Node node = new TextNode("text", "baseUri");
        xmlTreeBuilder.insertNode(node);
        Assert.assertEquals("text", xmlTreeBuilder.stack.getLast().outerHtml());
    }

    @Test
    public void insertCommentTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.Comment comment = new Token.Comment();
        comment.setData("test comment");
        xmlTreeBuilder.insert(comment);
        Assert.assertTrue(xmlTreeBuilder.stack.getLast() instanceof Comment);
    } 

    @Test(expected = IllegalArgumentException.class)
    public void popStackToCloseTest(){
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        Token.EndTag endTag = new Token.EndTag();
        endTag.tagName = "p";
        xmlTreeBuilder.insert(endTag);
        xmlTreeBuilder.popStackToClose(endTag);
        Assert.assertTrue(xmlTreeBuilder.stack.isEmpty());
    }    
}
